var import_obsidian5 = require("obsidian");

// src/ui/ActionButtons.ts
var import_obsidian4 = require("obsidian");

// src/ui/CommentModal.ts
var import_obsidian3 = require("obsidian");
var CommentModal = class extends import_obsidian3.Modal {
  constructor(app, action, onSubmit) {
    super(app);
    this.comment = "";
    this.action = action;
    this.onSubmit = onSubmit;
  }
  onOpen() {
    const { contentEl } = this;
    contentEl.createEl("h2", { text: `${this.action} Document` });
    contentEl.createEl("p", { text: `Add a comment for this ${this.action.toLowerCase()}:` });
    new import_obsidian3.TextAreaComponent(contentEl).setPlaceholder(`Enter your ${this.action.toLowerCase()} comment...`).setValue("").onChange((value) => this.comment = value);
    const buttonContainer = contentEl.createDiv("modal-button-container");
    new import_obsidian3.ButtonComponent(buttonContainer).setButtonText("Cancel").onClick(() => this.close());
    new import_obsidian3.ButtonComponent(buttonContainer).setButtonText(this.action).setCta().onClick(() => {
      this.onSubmit(this.comment);
      this.close();
    });
  }
};

// src/ui/ActionButtons.ts
var ActionButtons = class {
  // Will be properly typed when we extract the main plugin
  constructor(plugin) {
    this.plugin = plugin;
  }
  addActionButtons(container, doc, role, user) {
    const { file, workflow } = doc;
    switch (role) {
      case "author":
        if (workflow.state === "draft" || workflow.state === "rejected") {
          new import_obsidian4.ButtonComponent(container).setButtonText("Send to Review").onClick(() => this.plugin.sendToReview(file));
        }
        break;
      case "reviewer":
        if (workflow.state === "review") {
          new import_obsidian4.ButtonComponent(container).setButtonText("Approve").onClick(() => this.showCommentModal("Approve", (comment) => this.plugin.approveDocument(file, user, comment)));
          new import_obsidian4.ButtonComponent(container).setButtonText("Reject").onClick(() => this.showCommentModal("Reject", (comment) => this.plugin.rejectDocument(file, user, comment)));
        }
        break;
      case "publisher":
        if (workflow.state === "approved") {
          new import_obsidian4.ButtonComponent(container).setButtonText("Publish").onClick(() => this.plugin.publishDocument(file, user));
        }
        break;
      case "chief-editor":
        this.addChiefEditorActions(container, file, workflow, user);
        break;
    }
  }
  addChiefEditorActions(container, file, workflow, user) {
    switch (workflow.state) {
      case "draft":
      case "rejected":
        new import_obsidian4.ButtonComponent(container).setButtonText("Send to Review").onClick(() => this.plugin.sendToReview(file));
        break;
      case "review":
        new import_obsidian4.ButtonComponent(container).setButtonText("Approve").onClick(() => this.showCommentModal("Approve", (comment) => this.plugin.approveDocument(file, user, comment)));
        new import_obsidian4.ButtonComponent(container).setButtonText("Reject").onClick(() => this.showCommentModal("Reject", (comment) => this.plugin.rejectDocument(file, user, comment)));
        break;
      case "approved":
        new import_obsidian4.ButtonComponent(container).setButtonText("Publish").onClick(() => this.plugin.publishDocument(file, user));
        break;
    }
  }
  showCommentModal(action, onSubmit) {
    new CommentModal(this.plugin.app, action, (comment) => {
      onSubmit(comment);
      setTimeout(() => this.plugin.refreshWorkflowPanel(), 100);
    }).open();
  }
};

// src/ui/WorkflowPanel.ts
var WORKFLOW_VIEW_TYPE = "workflow-panel";
var WorkflowPanelView = class extends import_obsidian5.ItemView {
  constructor(leaf, plugin) {
    super(leaf);
    this.plugin = plugin;
    this.actionButtons = new ActionButtons(plugin);
  }
  getViewType() {
    return WORKFLOW_VIEW_TYPE;
  }
  getDisplayText() {
    const role = this.plugin.settings.currentRole;
    return role ? `Workflow (${role})` : "Workflow Panel";
  }
  getIcon() {
    return "workflow";
  }
  async onOpen() {
    await this.refresh();
  }
  async refresh() {
    const { contentEl } = this;
    contentEl.empty();
    if (!this.plugin.settings.currentUser) {
      contentEl.createEl("p", { text: "Please login to view workflow documents" });
      return;
    }
    const role = this.plugin.settings.currentRole;
    const user = this.plugin.settings.currentUser;
    contentEl.createEl("h3", { text: `Welcome, ${user} (${role})` });
    const documents = await this.getDocumentsForRole(role, user);
    if (documents.length === 0) {
      contentEl.createEl("p", { text: "No documents found for your role" });
      return;
    }
    const listEl = contentEl.createEl("div", { cls: "workflow-document-list" });
    for (const doc of documents) {
      const docEl = listEl.createEl("div", { cls: "workflow-document-item" });
      const headerEl = docEl.createEl("div", { cls: "workflow-document-header" });
      headerEl.createEl("span", { text: doc.file.basename, cls: "workflow-document-title" });
      headerEl.createEl("span", { text: doc.workflow.state.toUpperCase(), cls: `workflow-state-${doc.workflow.state}` });
      const metaEl = docEl.createEl("div", { cls: "workflow-document-meta" });
      metaEl.createEl("span", { text: `Created by: ${doc.workflow.createdBy}` });
      if (doc.workflow.history.length > 0) {
        const lastAction = doc.workflow.history[doc.workflow.history.length - 1];
        metaEl.createEl("span", { text: `Last action: ${lastAction.action} by ${lastAction.user}` });
      }
      const actionsEl = docEl.createEl("div", { cls: "workflow-document-actions" });
      this.actionButtons.addActionButtons(actionsEl, doc, role, user);
      docEl.addEventListener("click", () => {
        this.app.workspace.openLinkText(doc.file.path, "", false);
      });
    }
  }
  async getDocumentsForRole(role, user) {
    const files = this.app.vault.getMarkdownFiles();
    const documents = [];
    console.log(`[WorkflowPanel] Looking for documents for role: ${role}, user: ${user}`);
    console.log(`[WorkflowPanel] Found ${files.length} markdown files`);
    for (const file of files) {
      const workflow = await this.plugin.getDocumentWorkflow(file);
      console.log(`[WorkflowPanel] File: ${file.basename}, Workflow:`, workflow);
      if (!workflow)
        continue;
      let include = false;
      switch (role) {
        case "author":
          include = workflow.createdBy === user || workflow.state === "rejected" && workflow.createdBy === user;
          break;
        case "reviewer":
          include = workflow.state === "review";
          break;
        case "publisher":
          include = workflow.state === "approved";
          break;
        case "chief-editor":
          include = true;
          break;
      }
      if (include) {
        documents.push({ file, workflow });
      }
    }
    return documents;
  }
  // Action buttons are now handled by the ActionButtons component
};

