  parseWorkflowFromContent(content) {
    try {
      const frontmatterRegex = /^---\n(.*?)\n---/s;
      const match = content.match(frontmatterRegex);
      if (match) {
        const yamlContent = match[1];
        const workflowMatch = yamlContent.match(/^workflow:\s*((?:\n\s+.*)*)/m);
        if (workflowMatch) {
          const workflowSection = workflowMatch[1];
          return this.parseYamlWorkflow(workflowSection);
        }
      }
      return null;
    } catch (error) {
      console.error("[GitBranchManager] Error parsing workflow from content:", error);
      return null;
    }
  }
  parseYamlWorkflow(workflowSection) {
    try {
      const lines = workflowSection.split("\n");
      let state = null;
      let createdBy = null;
      let assignedTo = void 0;
      let history = [];
      let inHistorySection = false;
      let currentHistoryItem = {};
      for (let i = 0; i < lines.length; i++) {
        const line = lines[i];
        const trimmedLine = line.trim();
        if (!trimmedLine)
          continue;
        if (trimmedLine.startsWith("state:")) {
          state = trimmedLine.substring(6).trim();
        } else if (trimmedLine.startsWith("createdBy:")) {
          createdBy = trimmedLine.substring(10).trim();
        } else if (trimmedLine.startsWith("assignedTo:")) {
          assignedTo = trimmedLine.substring(11).trim();
        } else if (trimmedLine.startsWith("history:")) {
          inHistorySection = true;
        } else if (inHistorySection) {
          if (trimmedLine.startsWith("- ")) {
            if (currentHistoryItem.user && currentHistoryItem.role && currentHistoryItem.action && currentHistoryItem.timestamp) {
              history.push(currentHistoryItem);
            }
            currentHistoryItem = {};
            const itemContent = trimmedLine.substring(2).trim();
            if (itemContent) {
              const colonIndex = itemContent.indexOf(":");
              if (colonIndex > 0) {
                const key = itemContent.substring(0, colonIndex).trim();
                const value = itemContent.substring(colonIndex + 1).trim();
                currentHistoryItem[key] = value;
              }
            }
          } else if (trimmedLine.includes(":")) {
            const colonIndex = trimmedLine.indexOf(":");
            const key = trimmedLine.substring(0, colonIndex).trim();
            const value = trimmedLine.substring(colonIndex + 1).trim();
            currentHistoryItem[key] = value;
          }
        }
      }
      if (currentHistoryItem.user && currentHistoryItem.role && currentHistoryItem.action && currentHistoryItem.timestamp) {
        history.push(currentHistoryItem);
      }
      if (state && createdBy) {
        return {
          state,
          createdBy,
          assignedTo,
          history
        };
      }
      return null;
    } catch (error) {
      console.error("[GitBranchManager] Error parsing YAML workflow:", error);
      return null;
    }
  }
  updateWorkflowInContent(content, workflow) {
    const historyYaml = workflow.history.map(
      (h) => `  - user: ${h.user}
    role: ${h.role}
    action: ${h.action}
    timestamp: ${h.timestamp}${h.message ? `
    message: ${h.message}` : ""}`
    ).join("\n");
    const newWorkflowSection = `workflow:
  state: ${workflow.state}
  createdBy: ${workflow.createdBy}${workflow.assignedTo ? `
  assignedTo: ${workflow.assignedTo}` : ""}
  history:
${historyYaml}`;
    const frontmatterRegex = /^---\n(.*?)\n---/s;
    const match = content.match(frontmatterRegex);
    if (match) {
      const yamlContent = match[1];
      const updatedYaml = yamlContent.replace(/workflow:\s*((?:\n\s+.*)*)/s, newWorkflowSection);
      return content.replace(frontmatterRegex, `---
${updatedYaml}
---`);
    }
    return content;
  }
