// src/services/NotificationService.ts
var import_obsidian10 = require("obsidian");
var NotificationService = class {
  constructor(app) {
    this.notifications = [];
    this.listeners = [];
    this.maxNotifications = 50;
    this.app = app;
    this.loadNotifications();
  }
  // Add a new notification
  addNotification(notification) {
    console.log(`[NotificationService] addNotification called:`, notification);
    const newNotification = {
      ...notification,
      id: this.generateId(),
      timestamp: new Date(),
      read: false
    };
    this.notifications.unshift(newNotification);
    console.log(`[NotificationService] Notification added, total notifications:`, this.notifications.length);
    if (this.notifications.length > this.maxNotifications) {
      this.notifications = this.notifications.slice(0, this.maxNotifications);
    }
    this.saveNotifications();
    this.notifyListeners();
    console.log(`[NotificationService] Listeners notified`);
    if (newNotification.priority === "high" || newNotification.actionRequired) {
      new import_obsidian10.Notice(newNotification.title, 5e3);
    }
  }
  // Get all notifications
  getNotifications() {
    return this.notifications;
  }
  // Get unread notifications
  getUnreadNotifications() {
    return this.notifications.filter((n) => !n.read);
  }
  // Get notifications for specific role
  getNotificationsForRole(role) {
    return this.notifications.filter(
      (n) => !n.targetRole || n.targetRole === role || n.targetRole === "all"
    );
  }
  // Mark notification as read
  markAsRead(notificationId) {
    const notification = this.notifications.find((n) => n.id === notificationId);
    if (notification) {
      notification.read = true;
      this.saveNotifications();
      this.notifyListeners();
    }
  }
  // Mark all notifications as read
  markAllAsRead() {
    this.notifications.forEach((n) => n.read = true);
    this.saveNotifications();
    this.notifyListeners();
  }
  // Clear old notifications
  clearOldNotifications(daysOld = 7) {
    const cutoffDate = new Date();
    cutoffDate.setDate(cutoffDate.getDate() - daysOld);
    this.notifications = this.notifications.filter((n) => n.timestamp > cutoffDate);
    this.saveNotifications();
    this.notifyListeners();
  }
  // Clear all notifications
  clearAllNotifications() {
    this.notifications = [];
    this.saveNotifications();
    this.notifyListeners();
    console.log("[NotificationService] All notifications cleared");
  }
  // Subscribe to notification updates
  subscribe(listener) {
    this.listeners.push(listener);
    return () => {
      const index = this.listeners.indexOf(listener);
      if (index > -1) {
        this.listeners.splice(index, 1);
      }
    };
  }
  // Workflow-specific notification methods
  notifyDocumentCreated(documentName, author, branchName) {
    console.log(`[NotificationService] notifyDocumentCreated called:`, { documentName, author, branchName });
    this.addNotification({
      type: "document_created",
      title: "New Document Created",
      message: `${author} created a new document: ${documentName}`,
      documentName,
      author,
      branchName,
      priority: "medium",
      targetRole: "reviewer"
    });
    this.addNotification({
      type: "document_created",
      title: "Document Created",
      message: `You have created a new document: ${documentName}`,
      documentName,
      author,
      branchName,
      priority: "low",
      targetRole: "author"
    });
    console.log(`[NotificationService] \u2705 Document creation notifications added`);
  }
  notifyReviewRequested(documentName, author, branchName) {
    this.addNotification({
      type: "review_requested",
      title: "\u{1F50D} Review Requested",
      message: `${author} submitted "${documentName}" for review`,
      documentName,
      author,
      branchName,
      priority: "high",
      actionRequired: true,
      targetRole: "reviewer"
    });
    this.addNotification({
      type: "review_requested",
      title: "\u{1F50D} Review Requested",
      message: `You have submitted "${documentName}" for review`,
      documentName,
      author,
      branchName,
      priority: "medium",
      actionRequired: false,
      targetRole: "author"
    });
  }
  notifyDocumentApproved(documentName, reviewer, author) {
    this.addNotification({
      type: "document_approved",
      title: "\u2705 Document Approved",
      message: `${reviewer} approved "${documentName}" by ${author}`,
      documentName,
      author,
      reviewer,
      priority: "medium",
      targetRole: "publisher"
    });
  }
  notifyDocumentRejected(documentName, reviewer, author, reason) {
    this.addNotification({
      type: "document_rejected",
      title: "\u274C Document Rejected",
      message: `${reviewer} rejected "${documentName}" by ${author}${reason ? ` - ${reason}` : ""}`,
      documentName,
      author,
      reviewer,
      priority: "high",
      actionRequired: true,
      targetRole: "author"
    });
  }
  notifyDocumentPublished(documentName, publisher, author) {
    this.addNotification({
      type: "document_published",
      title: "\u{1F680} Document Published",
      message: `${publisher} published "${documentName}" by ${author}`,
      documentName,
      author,
      publisher,
      priority: "low",
      targetRole: "all"
    });
  }
  notifySystemError(operation, error, user) {
    this.addNotification({
      type: "system_error",
      title: "\u26A0\uFE0F System Error",
      message: `Error in ${operation}: ${error}`,
      documentName: "System",
      author: user,
      priority: "high",
      actionRequired: true,
      targetRole: "all"
    });
  }
  // Private methods
  generateId() {
    return `notification_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`;
  }
  notifyListeners() {
    console.log(`[NotificationService] notifyListeners called, notifying ${this.listeners.length} listeners`);
    this.listeners.forEach((listener, index) => {
      console.log(`[NotificationService] Notifying listener ${index + 1}`);
      listener([...this.notifications]);
    });
  }
  saveNotifications() {
    try {
      const data = JSON.stringify(this.notifications);
      localStorage.setItem("workflow-notifications", data);
    } catch (error) {
      console.error("[NotificationService] Failed to save notifications:", error);
    }
  }
  loadNotifications() {
    try {
      const data = localStorage.getItem("workflow-notifications");
      if (data) {
        const parsed = JSON.parse(data);
        this.notifications = parsed.map((n) => ({
          ...n,
          timestamp: new Date(n.timestamp)
        }));
      }
    } catch (error) {
      console.error("[NotificationService] Failed to load notifications:", error);
      this.notifications = [];
    }
  }
  // Format timestamp for display
  formatTimestamp(timestamp) {
    const now = new Date();
    const diffMs = now.getTime() - timestamp.getTime();
    const diffMinutes = Math.floor(diffMs / (1e3 * 60));
    const diffHours = Math.floor(diffMs / (1e3 * 60 * 60));
    const diffDays = Math.floor(diffMs / (1e3 * 60 * 60 * 24));
    if (diffMinutes < 1) {
      return "Just now";
    } else if (diffMinutes < 60) {
      return `${diffMinutes}m ago`;
    } else if (diffHours < 24) {
      return `${diffHours}h ago`;
    } else if (diffDays < 7) {
      return `${diffDays}d ago`;
    } else {
      return timestamp.toLocaleDateString();
    }
  }
  // Get notification icon based on type
  getNotificationIcon(type) {
    switch (type) {
      case "document_created":
        return "\u{1F4C4}";
      case "review_requested":
        return "\u{1F50D}";
      case "document_approved":
        return "\u2705";
      case "document_rejected":
        return "\u274C";
      case "document_published":
        return "\u{1F680}";
      case "system_error":
        return "\u26A0\uFE0F";
      default:
        return "\u{1F514}";
    }
  }
  // Get notification priority color
  getPriorityColor(priority) {
    switch (priority) {
      case "high":
        return "var(--text-error)";
      case "medium":
        return "var(--text-warning)";
      case "low":
        return "var(--text-muted)";
      default:
        return "var(--text-normal)";
    }
  }
};

