  getBasicAvailableActions(workflow) {
    const actions = [];
    if (!this.settings.currentUser || !this.settings.currentRole) {
      return actions;
    }
    const role = this.settings.currentRole;
    const isOwner = workflow.createdBy === this.settings.currentUser;
    switch (workflow.state) {
      case "draft":
        if (role === "author" && isOwner || role === "chief-editor") {
          actions.push("edit", "submit");
        }
        break;
      case "review":
        if (role === "reviewer" && !isOwner) {
          actions.push("approve", "reject");
        }
        if (role === "chief-editor") {
          actions.push("approve", "reject");
        }
        break;
      case "approved":
        if (role === "publisher" || role === "chief-editor") {
          actions.push("publish");
        }
        break;
      case "published":
        if (role === "chief-editor") {
          actions.push("revise");
        }
        break;
    }
    return actions;
  }
